  }),

  updateAccount: protectedProcedure
    .input(z.object({ id: uuid, name: z.string().min(1).max(200), isActive: z.boolean() }))
    .mutation(({ ctx, input }) =>
      ctx.db.account.update({
        where: { id: input.id },
        data: { name: input.name, isActive: input.isActive },
      }),
    ),

  // ── journal ───────────────────────────────────────────────────────────────
