            })),
          },
        },
      });
    }),
  ),

  /** DRAFT → SENT: writes the DR AR / CR Revenue journal entry. */
  postInvoice: protectedProcedure.input(uuid).mutation(({ ctx, input }) =>
    ctx.db.$transaction(async (tx) => {
